Chat::StatusEnum Chat::toStatusEnum(const utility::string_t& value) const
{
    
    if (value == utility::conversions::to_string_t("a")) {
        return StatusEnum::A;
    }
    
    if (value == utility::conversions::to_string_t("c")) {
        return StatusEnum::C;
    }
    
    if (value == utility::conversions::to_string_t("d")) {
        return StatusEnum::D;
    }
    
    throw std::invalid_argument("Invalid value for conversion to StatusEnum");
}


const utility::string_t Chat::fromStatusEnum(const StatusEnum value) const
{
    switch(value)
    {
        
        case StatusEnum::A: return utility::conversions::to_string_t("a");
        
        case StatusEnum::C: return utility::conversions::to_string_t("c");
        
        case StatusEnum::D: return utility::conversions::to_string_t("d");
        
    }
}

